//! 🧸️ Native installed Toy producer advances its real transaction and borrowed pages before granted closure.
use super::*;
#[test]
fn original_installed_toy_job_preserves_transaction_wire_borrowed_outcomes_and_physical_receipts(){
 use semio_framework_job::{InteractiveJob,JobOutcomeBorrow,JobOutcomeView,JobPayloadAuthority,StepContext,StepBudget,OperationId,Generation,CancelToken};
 let grant=toy_fixture_caller_policy().0.preparation;let operation=OperationId(98117);let generation=Generation(11);let mut sequence=0;let((cancel,cancel_birth),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||CancelToken::admit_root(grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(cancel_birth.retained_capacity_bytes,cancel_birth.released_bytes));let mut born=heap.requested_bytes;let mut released=heap.released_bytes;let((mut authority,authority_birth),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(authority_birth.retained_capacity_bytes,authority_birth.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;
 let(mut job,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ToyRunJob{unit:OriginalToyUnit::new(),emission:OriginalToyEmission::new(),phase:0,batch_units:0,scan:0,retraction:None,progress_source:None,counter_source:None,trace_source:None,payload_source:[0;4],payload_source_ready:false,payload_position:0,successor:None,writer_retirement:None,progress_retirement:None,purpose:ToolRunJobPurpose::Run,original:std::mem::ManuallyDrop::new(ToyRunJobOriginal{writer:ToolRunTickWriter::new(ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32])),provisional_counts:Vec::new()}),original_live:true,original_close:None,base_count:0,target:3,done:0,resumed_from:0,checkpoint_due:false,finished:false,closing:false});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let owner=std::ptr::addr_of!(job);let mut turns=0;let mut previews=0;let mut checkpoints=0;
 loop{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.step(&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));assert!(outcome.is_none());assert_eq!(cx.retained_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(std::ptr::addr_of!(job),owner);}
  let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(outcome,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.step(&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));let progress=cx.retained_progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;drop(cx);turns+=1;assert!(turns<10000);if let Some(mut descriptor)=outcome{let(view,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.borrow_outcome(&descriptor).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let complete=match view{JobOutcomeView::PreviewReady{payload,..}=>{let bytes:Vec<u8>=(0..payload.page_count()).flat_map(|page|payload.page(page).unwrap().iter().copied()).collect();let tick=ToolRunTick::decode(&bytes).unwrap();assert_eq!(tick.append_ops.len(),6);assert_eq!(tick.append_entities,[1,2,3]);previews+=1;false},JobOutcomeView::CheckpointReady{state,applied_progress,..}=>{assert_eq!(applied_progress,3);assert_eq!(state.page(0).unwrap(),3u32.to_le_bytes());checkpoints+=1;false},JobOutcomeView::Complete{state:None,output:None,..}=>true,_=>panic!("unexpected original Toy descriptor")};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||descriptor.acknowledge(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(descriptor);if complete{break}}
 }
 assert_eq!((previews,checkpoints),(1,1));assert_eq!(job.done,3);job.begin_close();while !job.terminal_is_empty(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.close_step(grant));assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;turns+=1;assert!(turns<20000)}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||authority.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.released_bytes;let mut cancellation=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !cancellation.terminal_is_empty(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cancellation.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));released+=heap.released_bytes;}assert_eq!(born,released);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{drop(job);drop(authority);drop(cancellation)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] actual installed Toy3units6nativeops3entities preview1 checkpoint1 CompleteNone borrowedOwner={owner:p} all4receipt physical={released} paidTurns={turns} original5axes deniedHeap0 ACKmetadata0 terminalDrop0; enclosingMountedConsumerSeparate");
}
